const root="/home/axel/LeanAlgebraicGeometry-Horizon";
const proj="/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild";
const calls = [
  tools.exec_command({cmd:"\"$HORIZON_BIN\" search \"tensor product algebra equivalence congr\" --json",workdir:proj,yield_time_ms:10000,max_output_tokens:20000}),
  tools.exec_command({cmd:"rg -n \"TensorProduct.*congr|AlgEquiv.*congr|def congr|isoIsPushout|inl_isoIsPushout|inr_isoIsPushout\" /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/RingTheory /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib/CategoryTheory -g '*.lean'",workdir:proj,yield_time_ms:10000,max_output_tokens:30000}),
  tools.exec_command({cmd:"rg -n \"namespace CommRingCat|isPushout_tensorProduct|isoIsPushout|inl_isoIsPushout\" /home/axel/LeanAlgebraicGeometry-Horizon/.lake-packages/mathlib/Mathlib -g '*.lean'",workdir:proj,yield_time_ms:10000,max_output_tokens:30000})
];
const rs=await Promise.all(calls); rs.forEach((r,i)=>text(`---${i+1}---\n${r.output}`));

const rs = await Promise.all([
  tools.mcp__lean_lsp__lean_leansearch({query:"algebra equivalence between tensor products induced by equivalences of base ring and two algebras",num_results:30}),
  tools.mcp__lean_lsp__lean_loogle({query:"TensorProduct.*congr",num_results:30}),
  tools.mcp__lean_lsp__lean_loogle({query:"AlgEquiv TensorProduct",num_results:30})
]);
rs.forEach((r,i)=>{text(`### ${i}`);text(r);});

